//! Lists `src/vendors/*.rs`, so a new CLI is one new file there and never an
//! edit to shared code. Each file must export `pub struct V` implementing
//! `crate::decl::Vendor` (`unobserved!` writes it for a CLI that is only
//! launched and resumed). The generated file declares the modules and a
//! macro that hands their names on (`src/registry.rs` builds the registry
//! from it).
use std::fmt::Write as _;
use std::path::Path;

fn main() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join("vendors");
    println!("cargo:rerun-if-changed={}", dir.display());
    let mut keys: Vec<String> = std::fs::read_dir(&dir)
        .expect("src/vendors is readable")
        .filter_map(|entry| {
            let path = entry.ok()?.path();
            let stem = path.file_stem()?.to_str()?.to_owned();
            (path.extension()? == "rs" && !stem.starts_with('_')).then_some(stem)
        })
        .collect();
    keys.sort();
    let mut out = String::from("/// Every declared CLI (generated by build.rs from `src/vendors/*.rs`).\npub mod vendors {\n");
    for key in &keys {
        let file = dir.join(format!("{key}.rs"));
        println!("cargo:rerun-if-changed={}", file.display());
        writeln!(out, "    #[path = {:?}]\n    pub mod {key};", file.display().to_string()).unwrap();
    }
    out.push_str("}\n\n/// Calls the given macro with every vendor module's name, sorted.\nmacro_rules! each_vendor {\n    ($with:ident) => {\n        $with! {");
    for key in &keys {
        write!(out, " {key},").unwrap();
    }
    out.push_str(" }\n    };\n}\n");
    let target = Path::new(&std::env::var("OUT_DIR").unwrap()).join("vendors.rs");
    std::fs::write(target, out).unwrap();
}
